 if(/^custom:/i.test(raw))return customReactionLabel(raw);
 if(AI_REACTION_NAME_BY_ID[raw]||LEGACY_AI_REACTION_NAME_BY_ID[raw])return AI_REACTION_NAME_BY_ID[raw]||LEGACY_AI_REACTION_NAME_BY_ID[raw];
 return raw;
