function aiThemeName(item){return String(item?.name||item?.proposedName||item?.label||item?.code||'Unknown').trim()}
function average(values){const nums=values.filter(Number.isFinite);return nums.length?Math.round(nums.reduce((a,b)=>a+b,0)/nums.length*10)/10:null}
function reportFilename(record){return record?.source?.originalFilename||record?.source?.originalUrl||record?.name||record?.id||'Unknown image'}
function primFusionLabel(record){const d=record?.analysis?.director||{},rs=directorReactions(record);return d.primFusion?.label||d.primFusion?.id||(rs.length>=2?rs.slice(0,2).join(' × '):'')}
function directorRecordedAt(record){const d=record?.analysis?.director||{};const value=d.recordedAt||d.updatedAt||d.timestamp||record?.timestamps?.processedAt||'';return Number.isFinite(Date.parse(value))?String(value):''}
function meaningfulDirectorState(state){if(!state||typeof state!=='object')return false;return (state.reactions||state.selectedReactions||[]).length>0||(state.themes||[]).some(Boolean)||Boolean(state.primFusion)||Boolean(String(state.notes||state.writeIn||'').trim())||Boolean(state.flagged)||Boolean(state.saved)||!['','unclassified'].includes(String(state.completion||'').toLowerCase())}
function comparableDirectorState(state){if(!state||typeof state!=='object')return null;return{reactions:[...(state.reactions||state.selectedReactions||[])],themes:[...(state.themes||[])],primFusion:clone(state.primFusion||null),notes:String(state.notes||state.writeIn||''),flagged:Boolean(state.flagged),saved:Boolean(state.saved),retention:String(state.retention||''),completion:String(state.completion||'')}}
