 if(modules.includes('primfusion')){const counts={};for(const r of items){const d=r.analysis?.director||{};const key=d.primFusion?.label||d.primFusion?.id||(directorReactions(r).length>=2?directorReactions(r).join(' × '):'');increment(counts,key)}result.primfusion={counts};}
 if(modules.includes('agreement')){const comparableItems=items.filter(directorComplete);const reactions=new Set(comparableItems.flatMap(r=>[...directorReactions(r),...aiReactionNames(r)]));const byReaction={};for(const name of reactions){let comparable=0,agree=0,highAiDirectorNo=0;for(const r of comparableItems){const score=aiReactionScore(r,name);if(!Number.isFinite(score))continue;comparable++;const selected=directorReactions(r).includes(name),aiYes=score>=50;if(selected===aiYes)agree++;if(!selected&&score>=70)highAiDirectorNo++;}byReaction[name]={comparable,agree,agreementRate:comparable?Math.round(agree/comparable*1000)/10:null,highAiDirectorNo};}result.agreement={byReaction};}
 if(modules.includes('sources')){const counts={};items.forEach(r=>increment(counts,r.source?.type||'unknown'));result.sources={counts};}
